import React, { useState } from "react";
import "./ClientsList.css";

const Clients = [
  //cambiar despues
  {
    id: 1,
    title: "Cliente 1",
    businessArea: "Auditoria",
    invoices: [
      { id: 10010125, date: "2024-01-10" },
      { id: 10212012, date: "2024-02-15" },
    ],
  },
  {
    id: 2,
    title: "Cliente 2",
    businessArea: "Auditoria de TI y Cumplimiento normativo",
    invoices: [
      { id: 20010125, date: "2024-03-01" },
      { id: 20010126, date: "2024-04-20" },
    ],
  },
  {
    id: 3,
    title: "Cliente 3",
    businessArea: "BPO",
    invoices: [],
  },
  {
    id: 4,
    title: "Cliente 4",
    businessArea: "Finanzas Corporativas",
    invoices: [],
  },
  {
    id: 5,
    title: "Cliente 5",
    businessArea: "Impuestos",
    invoices: [],
  },
  {
    id: 6,
    title: "Cliente 6",
    businessArea: "Impuestos",
    invoices: [],
  },
  {
    id: 7,
    title: "Cliente 7",
    businessArea: "RAS",
    invoices: [],
  },
];

const businessOptions = [
  { value: "Auditoria", label: "Auditoria" },
  {
    value: "Auditoria de TI y Cumplimiento normativo",
    label: "Auditoria de TI y Cumplimiento Normativo",
  },
  { value: "BPO", label: "BPO" },
  { value: "Finanzas Corporativas", label: "Finanzas Corporativas" },
  { value: "Impuestos", label: "Impuestos" },
  { value: "Precios de Transferencia", label: "Precios de Transferencia" },
  { value: "RAS", label: "RAS" },
  { value: "Consultoria de Negocios", label: "Consultoria de Negocios" },
  { value: "TI - Consultoria", label: "TI - Consultoria" },
  { value: "TI - Administracion", label: "TI - Administracion" },
  { value: "Administracion", label: "Administracion" },
  { value: "Desarrollo de Negocios", label: "Desarrollo de Negocios" },
];

const compareOptions = [
  { value: "", label: "Sin elegir" },

  { value: "thisMonth", label: "Este mes" },
  { value: "thisQuarter", label: "Este trimestre" },
  { value: "thisFourMonth", label: "Este cuatrimestre" },
  { value: "thisYear", label: "Este año" },

  { value: "lastMonth", label: "Último mes" },
  { value: "lastQuarter", label: "Último trimestre" },
  { value: "lastFourMonth", label: "Último cuatrimestre" },
  { value: "lastYear", label: "Último año" },

  { value: "monthToDate", label: "Mes hasta la fecha" },
  { value: "quarterToDate", label: "Trimestre hasta la fecha" },
  { value: "fourMonthToDate", label: "Cuatrimestre hasta la fecha" },
  { value: "yearToDate", label: "Año hasta la fecha" },

  { value: "custom", label: "Personalizado" },
];

const ClientsList = () => {
  const [query, setQuery] = useState("");
  const [businessFilter, setBusinessFilter] = useState("");
  const [clientFilters, setClientFilters] = useState({});
  const [activeClient, setActiveClient] = useState(null);
  const [comparePeriod, setComparePeriod] = useState({});

  const filteredClients = Clients.filter((client) => {
    const matchesSearch = client.title
      .toLowerCase()
      .includes(query.toLowerCase());

    const matchesBusiness =
      businessFilter === "" ||
      client.businessArea === businessFilter;

    return matchesSearch && matchesBusiness;
  });

  const applyClientFilters = (client) => {
    const filters = clientFilters[client.id];
    let results = [...(client.invoices || [])];

    if (!filters) return results;

    if (filters.dateFrom && filters.dateTo) {
      results = results.filter((invoice) => {
        const date = new Date(invoice.date);

        return (
          date >= new Date(filters.dateFrom) &&
          date <= new Date(filters.dateTo)
        );
      });
    }

    return results;
  };

  const handleFilterChange = (clientId, field, value) => {
    setClientFilters((prev) => ({
      ...prev,
      [clientId]: {
        ...prev[clientId],
        [field]: value,
      },
    }));
  };

  return (
    <div className="clients-list">
      <div className="filter-bar">
        <select
          value={businessFilter}
          onChange={(e) => setBusinessFilter(e.target.value)}
        >
          <option value="">Todas las áreas</option>

          {businessOptions.map((opt) => (
            <option key={opt.value} value={opt.value}>
              {opt.label}
            </option>
          ))}
        </select>
      </div>

      <h2 className="Title">Clientes</h2>

      <input
        className="searcher"
        type="search"
        placeholder="Buscar cliente..."
        value={query}
        onChange={(e) => setQuery(e.target.value)}
      />

      <div className="clients-length">
        {filteredClients.length === 0 ? (
          <p className="no-results">
            No existen clientes con ese criterio de búsqueda
          </p>
        ) : (
          filteredClients.map((client) => {
            const filteredInvoices = applyClientFilters(client);

            return (
              <div key={client.id} className="client-card">
                <h3>{client.title}</h3>

                <p>
                  <strong>Área:</strong> {client.businessArea}
                </p>

                <button
                  onClick={() =>
                    setActiveClient(
                      activeClient === client.id ? null : client.id
                    )
                  }
                >
                  Filtro
                </button>

                {activeClient === client.id && (
                  <div className="filter-panel">
                    <p>Rango de fechas:</p>

                    <div className="date-group">
                      <input
                        type="date"
                        onChange={(e) =>
                          handleFilterChange(
                            client.id,
                            "dateFrom",
                            e.target.value
                          )
                        }
                      />

                      <input
                        type="date"
                        onChange={(e) =>
                          handleFilterChange(
                            client.id,
                            "dateTo",
                            e.target.value
                          )
                        }
                      />
                    </div>

                    <p>Comparar con:</p>

                    <div className="compare-group">
                      <select
                        value={comparePeriod[client.id] || ""}
                        onChange={(e) =>
                          setComparePeriod((prev) => ({
                            ...prev,
                            [client.id]: e.target.value,
                          }))
                        }
                      >
                        {compareOptions.map((option) => (
                          <option
                            key={option.value}
                            value={option.value}
                          >
                            {option.label}
                          </option>
                        ))}
                      </select>

                      {comparePeriod[client.id] === "custom" && (
                        <div className="date-group">
                          <input type="date" />
                          <input type="date" />
                        </div>
                      )}
                    </div>

                    <h4>Facturas</h4>

                    {filteredInvoices.length === 0 ? (
                      <p>No hay facturas para mostrar.</p>
                    ) : (
                      <ul>
                        {filteredInvoices.map((invoice) => (
                          <li key={invoice.id}>
                            Factura #{invoice.id} - {invoice.date}
                          </li>
                        ))}
                      </ul>
                    )}
                  </div>
                )}
              </div>
            );
          })
        )}
      </div>
    </div>
  );
};

export default ClientsList;
